package android.system;public final class Os{private static final java.util.Map<java.io.FileDescriptor,java.nio.channels.FileChannel> files=new java.util.IdentityHashMap<>();public static synchronized java.io.FileDescriptor open(String path,int flags,int mode)throws ErrnoException{try{java.io.FileDescriptor d=new java.io.FileDescriptor();files.put(d,java.nio.channels.FileChannel.open(java.nio.file.Paths.get(path),java.nio.file.StandardOpenOption.READ));return d;}catch(java.io.IOException e){throw new ErrnoException(e.toString(),1);}}public static synchronized void fsync(java.io.FileDescriptor d)throws ErrnoException{try{files.get(d).force(true);}catch(java.io.IOException e){throw new ErrnoException(e.toString(),1);}}public static synchronized void close(java.io.FileDescriptor d)throws ErrnoException{try{java.nio.channels.FileChannel c=files.remove(d);if(c!=null)c.close();}catch(java.io.IOException e){throw new ErrnoException(e.toString(),1);}}}